import { render } from "./engine";

async function main(): Promise<void> {
  const [templatePath, dataPath, ...extra] = Bun.argv.slice(2);
  if (!templatePath || !dataPath || extra.length > 0) {
    throw new Error("Usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
  }

  const [template, json] = await Promise.all([
    Bun.file(templatePath).text(),
    Bun.file(dataPath).text(),
  ]);
  const data: unknown = JSON.parse(json);
  process.stdout.write(render(template, data));
}

main().catch((error: unknown) => {
  const message = error instanceof Error ? error.message : String(error);
  console.error(`mini-template: ${message}`);
  process.exitCode = 1;
});
type Position = { line: number; column: number };

type Node =
  | { kind: "text"; value: string }
  | { kind: "value"; path: string; escaped: boolean; position: Position }
  | {
      kind: "block";
      block: "if" | "each";
      path: string;
      truthy: Node[];
      falsy: Node[];
      position: Position;
    };

type BlockNode = Extract<Node, { kind: "block" }>;
type Frame = { node: BlockNode; branch: "truthy" | "falsy" };
type LoopContext = { value: unknown; index: number };

export class TemplateError extends Error {
  readonly line: number;
  readonly column: number;

  constructor(message: string, position: Position) {
    super(`${message} at line ${position.line}, column ${position.column}`);
    this.name = "TemplateError";
    this.line = position.line;
    this.column = position.column;
  }
}

function positionAt(source: string, offset: number): Position {
  let line = 1;
  let column = 1;
  for (let i = 0; i < offset; i++) {
    if (source.charCodeAt(i) === 10) {
      line++;
      column = 1;
    } else {
      column++;
    }
  }
  return { line, column };
}

function parse(template: string): Node[] {
  const root: Node[] = [];
  const stack: Frame[] = [];
  let nodes = root;
  let cursor = 0;

  while (cursor < template.length) {
    const start = template.indexOf("{{", cursor);
    if (start === -1) {
      nodes.push({ kind: "text", value: template.slice(cursor) });
      break;
    }
    if (start > cursor) nodes.push({ kind: "text", value: template.slice(cursor, start) });

    const triple = template.startsWith("{{{", start);
    const closing = triple ? "}}}" : "}}";
    const contentStart = start + (triple ? 3 : 2);
    const end = template.indexOf(closing, contentStart);
    const position = positionAt(template, start);
    if (end === -1) throw new TemplateError("Unclosed tag", position);

    const content = template.slice(contentStart, end).trim();
    cursor = end + closing.length;

    if (triple) {
      nodes.push({ kind: "value", path: content, escaped: false, position });
      continue;
    }
    if (content.startsWith("!")) continue;

    if (content.startsWith("#")) {
      const match = /^#(if|each)(?:\s+(.+))?$/.exec(content);
      if (!match) {
        const name = content.slice(1).split(/\s/, 1)[0] || "(empty)";
        throw new TemplateError(`Unknown block '${name}'`, position);
      }
      const path = match[2]?.trim();
      if (!path) throw new TemplateError(`Block '${match[1]}' requires a path`, position);
      const node: BlockNode = {
        kind: "block",
        block: match[1] as "if" | "each",
        path,
        truthy: [],
        falsy: [],
        position,
      };
      nodes.push(node);
      stack.push({ node, branch: "truthy" });
      nodes = node.truthy;
      continue;
    }

    if (content === "else") {
      const frame = stack.at(-1);
      if (!frame) throw new TemplateError("'else' outside a block", position);
      if (frame.branch === "falsy") throw new TemplateError("Duplicate 'else'", position);
      frame.branch = "falsy";
      nodes = frame.node.falsy;
      continue;
    }

    if (content.startsWith("/")) {
      const name = content.slice(1).trim();
      const frame = stack.at(-1);
      if (!frame) throw new TemplateError(`Unexpected closing block '${name}'`, position);
      if (name !== frame.node.block) {
        throw new TemplateError(
          `Mismatched closing block '${name}'; expected '${frame.node.block}'`,
          position,
        );
      }
      stack.pop();
      const parent = stack.at(-1);
      nodes = parent
        ? parent.branch === "truthy"
          ? parent.node.truthy
          : parent.node.falsy
        : root;
      continue;
    }

    nodes.push({ kind: "value", path: content, escaped: true, position });
  }

  const unclosed = stack.at(-1)?.node;
  if (unclosed) {
    throw new TemplateError(`Unclosed block '${unclosed.block}'`, unclosed.position);
  }
  return root;
}

function property(value: unknown, key: string): { found: boolean; value: unknown } {
  if ((typeof value !== "object" || value === null) && typeof value !== "function") {
    return { found: false, value: undefined };
  }
  if (!Object.prototype.hasOwnProperty.call(value, key)) return { found: false, value: undefined };
  return { found: true, value: (value as Record<string, unknown>)[key] };
}

function walk(base: unknown, parts: string[]): { found: boolean; value: unknown } {
  let value = base;
  for (const part of parts) {
    const next = property(value, part);
    if (!next.found) return next;
    value = next.value;
  }
  return { found: true, value };
}

function resolve(path: string, root: unknown, loops: LoopContext[]): unknown {
  const current = loops.at(-1);
  if (path === "this") return current?.value;
  if (path === "@index") return current?.index;

  if (path.startsWith("this.")) {
    return current ? walk(current.value, path.slice(5).split(".")).value : undefined;
  }

  const parts = path.split(".");
  if (current) {
    const local = walk(current.value, parts);
    if (local.found) return local.value;
  }
  return walk(root, parts).value;
}

function isTruthy(value: unknown): boolean {
  if (Array.isArray(value)) return value.length > 0;
  return !(value === "" || value === 0 || value === false || value == null);
}

function scalar(value: unknown, path: string, position: Position): string {
  if (value == null) return "";
  switch (typeof value) {
    case "string":
    case "number":
    case "bigint":
    case "boolean":
      return String(value);
    default:
      throw new TemplateError(`Value '${path}' is not scalar and cannot be rendered`, position);
  }
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => {
    switch (character) {
      case "&": return "&amp;";
      case "<": return "&lt;";
      case ">": return "&gt;";
      case '"': return "&quot;";
      default: return "&#39;";
    }
  });
}

function renderNodes(nodes: Node[], root: unknown, loops: LoopContext[]): string {
  let output = "";
  for (const node of nodes) {
    if (node.kind === "text") {
      output += node.value;
    } else if (node.kind === "value") {
      const text = scalar(resolve(node.path, root, loops), node.path, node.position);
      output += node.escaped ? escapeHtml(text) : text;
    } else {
      const value = resolve(node.path, root, loops);
      if (node.block === "if") {
        output += renderNodes(isTruthy(value) ? node.truthy : node.falsy, root, loops);
      } else if (Array.isArray(value) && value.length > 0) {
        for (let index = 0; index < value.length; index++) {
          output += renderNodes(node.truthy, root, [...loops, { value: value[index], index }]);
        }
      } else {
        output += renderNodes(node.falsy, root, loops);
      }
    }
  }
  return output;
}

/** Render a Mini Template string with the supplied data. */
export function render(template: string, data: unknown): string {
  return renderNodes(parse(template), data, []);
}
